def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def step_toward(a, b):
        return [clamp_step(b[0] - a[0]), clamp_step(b[1] - a[1])]

    def dist1(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def as_pair(x, default=(0, 0)):
        try:
            if isinstance(x, (list, tuple)) and len(x) >= 2:
                return [int(x[0]), int(x[1])]
        except:
            pass
        return [default[0], default[1]]

    def best_by(items, key_fn, reverse=False):
        try:
            return sorted(items, key=key_fn, reverse=reverse)[0] if items else None
        except:
            best = None
            best_key = None
            for it in items or []:
                try:
                    k = key_fn(it)
                except:
                    continue
                if best is None or (k > best_key if reverse else k < best_key):
                    best = it
                    best_key = k
            return best

    env = observation.get("environment_name", "resource_collection")
    self_pos = as_pair(observation.get("self_position", [0, 0]))
    opp_pos = as_pair(observation.get("opponent_position", self_pos))
    gw = int(observation.get("grid_width", 0) or 0)
    gh = int(observation.get("grid_height", 0) or 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)
        corners = [[0, 0], [0, max(0, gh - 1)], [max(0, gw - 1), 0], [max(0, gw - 1), max(0, gh - 1)]]
        target = best_by(corners, lambda c: dist1(c, opp_pos), reverse=True) or [0, 0]
        return step_toward(self_pos, target)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier_cells") or []
        parsed = []
        for t in targets:
            parsed.append(as_pair(t, self_pos))
        if parsed:
            target = best_by(parsed, lambda c: (dist1(c, self_pos), dist1(c, opp_pos)))
            return step_toward(self_pos, target)
        # fallback: move away from opponent / toward center if known
        if gw > 0 and gh > 0:
            center = [gw // 2, gh // 2]
            if dist1(self_pos, opp_pos) <= 2:
                # escape
                away = [self_pos[0] + clamp_step(self_pos[0] - opp_pos[0]),
                        self_pos[1] + clamp_step(self_pos[1] - opp_pos[1])]
                return step_toward(self_pos, away)
            return step_toward(self_pos, center)
        return [0, 0]

    resources = observation.get("resources") or observation.get("resource_positions") or []
    parsed = []
    for r in resources:
        parsed.append(as_pair(r, self_pos))

    if parsed:
        # Prefer closer resources, but slightly bias toward those far from opponent to reduce contests.
        target = best_by(parsed, lambda c: (dist1(c, self_pos) + max(0, 3 - dist1(c, opp_pos))))
        return step_toward(self_pos, target)

    # Generic fallback: if no resources, drift toward opponent to contest/pressure.
    if env == "resource_collection":
        if gw > 0 and gh > 0:
            center = [gw // 2, gh // 2]
            if dist1(self_pos, opp_pos) > 4:
                return step_toward(self_pos, center)
        return step_toward(self_pos, opp_pos)

    return [0, 0]

